// changeRecordBody builds a v1 release-record request whose entries are given
// in the listed order. Sequence is assigned by position when seq is zero.
func changeRecordBody(environment, version, gate, rollback string, entries ...string) string {
	body := `{"environment":"` + environment + `","version":"` + version + `",
		"changes":[` + strings.Join(entries, ",") + `],
		"gate_status":"` + gate + `","rollback_point":"` + rollback + `"}`
	return body
}

func withBatch(body, batchID string) string {
	return strings.Replace(body, `,"changes"`, `,"batch_id":"`+batchID+`","changes"`, 1)
}

func entryWithSeq(seq int, category, title, description string) string {
	return entry(seq, category, title, description)
}

func entryNoSeq(category, title, description string) string {
	return `{"category":"` + category + `","title":"` + title + `","description":"` + description + `"}`
}

func getChangesOK(t *testing.T, router *gin.Engine, target string) ([]any, string) {
	t.Helper()
	recorder := doRequest(t, router, http.MethodGet, target, "")
	if recorder.Code != http.StatusOK {
		t.Fatalf("GET %s status = %d (body %s)", target, recorder.Code, recorder.Body.String())
	}
	body := decodeBody(t, recorder)
	if len(body) != 2 {
		t.Fatalf("response must contain only changes and next_cursor: %s", recorder.Body.String())
	}
	changes, ok := body["changes"].([]any)
	if !ok {
		t.Fatalf("changes missing in %s", recorder.Body.String())
	}
	return changes, body["next_cursor"].(string)
}

func itemIDs(changes []any) []string {
	ids := make([]string, len(changes))
	for i, change := range changes {
		ids[i] = change.(map[string]any)["title"].(string)
	}
	return ids
}

// TestListChangeEntriesOrderingAndView verifies the global ordering: owning
// record newest first, and inside one record sequence then title ascending.
func TestListChangeEntriesOrderingAndView(t *testing.T) {
	router := newTestRouter(t)
	registerEnvironmentOK(t, router, "prod")

	// First record: three entries with explicit out-of-order positions and a
	// sequence tie to exercise the title tiebreaker.
	first := createRecordOK(t, router, changeRecordBody("prod", "1.0.0", "allowed", "snap:0.9.0",
		entryWithSeq(2, "feature", "zeta", "z desc"),
		entryWithSeq(1, "feature", "beta", "b desc"),
		entryWithSeq(1, "fix", "alpha", "a desc")))
	second := createRecordOK(t, router, changeRecordBody("prod", "1.1.0", "blocked", "snap:1.0.0",
		entryNoSeq("feature", "gamma", "g desc")))

	changes, next := getChangesOK(t, router, "/api/v1/change-entries")
	if next != "" {
		t.Fatalf("single page must return empty next_cursor, got %q", next)
	}
	if got := itemIDs(changes); len(got) != 4 ||
		got[0] != "gamma" || got[1] != "alpha" || got[2] != "beta" || got[3] != "zeta" {
		t.Fatalf("ordering = %v", got)
	}

	// The newest entry carries its owning record fields; sequence is assigned
	// by position when omitted.
	top := changes[0].(map[string]any)
	if top["sequence"] != float64(1) || top["category"] != "feature" ||
		top["title"] != "gamma" || top["description"] != "g desc" {
		t.Fatalf("top entry = %v", top)
	}
	if top["id"] != second["id"] || top["environment"] != "prod" || top["version"] != "1.1.0" ||
		top["gate_status"] != "blocked" || top["rollback_point"] != "snap:1.0.0" ||
		top["recorded_at"] != second["recorded_at"] {
		t.Fatalf("owning record fields wrong: %v", top)
	}
	if _, present := top["batch_id"]; present {
		t.Fatalf("batch_id must be omitted for unbatched records: %v", top)
	}

	// Entries of the first record expose auto/fixed sequences and its id.
	alpha := changes[1].(map[string]any)
	if alpha["sequence"] != float64(1) || alpha["id"] != first["id"] ||
		alpha["recorded_at"] != first["recorded_at"] || alpha["version"] != "1.0.0" {
		t.Fatalf("alpha entry = %v", alpha)
	}
	if zeta := changes[3].(map[string]any); zeta["sequence"] != float64(2) {
		t.Fatalf("zeta sequence = %v", zeta)
	}
}

