		{"/api/v1/change-entries?title=add+login", []string{"add login", "add login"}},
		{"/api/v1/change-entries?gate_status=pending", []string{"cleanup"}},
		{"/api/v1/change-entries?environment=prod&category=feature&gate_status=allowed&batch_id=b-1&version=1.0.0",
