func TestListChangeEntriesPaginationCoversEveryEntryOnce(t *testing.T) {
	router := newTestRouter(t)
	registerEnvironmentOK(t, router, "prod")
	const records = 3
	const perRecord = 2
	for i := 1; i <= records; i++ {
		createRecordOK(t, router, changeRecordBody("prod", "1.0."+numberToString(float64(i)),
			"allowed", "r", "",
			entry(1, "feature", "entry-a", "d"),
			entry(2, "fix", "entry-b", "d")))
	}

	target := "/api/v1/change-entries?limit=2"
	seen := map[string]bool{}
	var order []string
	pages := 0
	for {
		_, changes, next := listChanges(t, router, target)
		for _, raw := range changes {
			item := raw.(map[string]any)
			key := changeKey(item)
			if seen[key] {
				t.Fatalf("entry %s appeared on two pages", key)
			}
			seen[key] = true
			order = append(order, key)
		}
		pages++
		if next == "" {
			break
		}
		target = "/api/v1/change-entries?limit=2&cursor=" + next
		if pages > records*perRecord {
			t.Fatalf("pagination never terminated")
		}
	}
	if len(seen) != records*perRecord {
		t.Fatalf("seen %d unique entries, want %d: %v", len(seen), records*perRecord, order)
	}
	if pages != 3 {
		t.Fatalf("pages = %d, want 3", pages)
	}
	// Newest record (version 1.0.3, written last) leads; within a record seq 1 precedes seq 2.
	if !strings.HasPrefix(order[0], "rel_/1/entry-a") {
		t.Fatalf("first ordered key = %s", order[0])
	}
}

