	instant, err := time.Parse("2006-01-02T15:04:05Z", raw)
	if err != nil {
		return "", err
	}
	canonical := instant.UTC().Format("2006-01-02T15:04:05Z")
	if raw != canonical {
		return "", errNonCanonicalTime
	}
	return canonical, nil
}
